#include "test_boot_reason.h"
#include "../../../../../tf_common/tf_uart_comms.h"
#include "../../../../../tf_common/tf_test_results.h"
#include <Hal.h>
#include <stdio.h>


// Populates pString with the given reset reason
void get_reset_reason_as_string(enum Reset_Reason iResetReason, char * pString)
{
    switch (iResetReason) {
        case Reset_Reason_Powerup:
            sprintf(pString, "'Power-On Reset'");
            break;
        case Reset_Reason_Backup:
            sprintf(pString, "'Backup Reset'");
            break;
        case Reset_Reason_Watchdog:
            sprintf(pString, "'Watchdog Reset'");
            break;
        case Reset_Reason_Software:
            sprintf(pString, "'Software Reset'");
            break;
        case Reset_Reason_User:
            sprintf(pString, "'User Reset'");
            break;
        default:
            sprintf(pString, "UNKNOWN (%d)", iResetReason);
    }
}


// Constructor
void test_boot_reason_startup(void)
{
    // Register the test that this TASTE Function will submit a result for
    testresult_register_test(TF_TEST_ID__TestBootReason);
}


// Handler for cyclic IF: Validates a boot reason can be fetched from the runtime
void test_boot_reason_PI_trigger_check(void)
{
    char aMsgBuff[100];
    char aTmp[40];
    static asn1SccT_Boolean bResultReported = false;

    // Only do this once
    if (bResultReported) {
        return;
    }

    // Get and render the reset reason
    enum Reset_Reason iResetReason = Hal_GetResetReason();
    get_reset_reason_as_string(iResetReason, aTmp);
    sprintf(aMsgBuff, "Reset reason: %s", aTmp);
    transmit_log_info(aMsgBuff);

    // This test always passes if we got this far - and reset reason is not "unknown"
    if (   iResetReason == Reset_Reason_Powerup
        || iResetReason == Reset_Reason_Backup
        || iResetReason == Reset_Reason_Watchdog
        || iResetReason == Reset_Reason_Software
        || iResetReason == Reset_Reason_User
    ) {
        testresult_report_pass(TF_TEST_ID__TestBootReason);
    } else {
        sprintf(aMsgBuff, "Reset reason unrecognised: %i", iResetReason);
        testresult_report_fail(TF_TEST_ID__TestBootReason, aMsgBuff);
    }

    // Set flag to ensure we do not do this again
    bResultReported = true;
}


